import React from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import styles from './AcceptancePage.module.css';

const AcceptancePage = () => {
  // Dados mocados para a lista de provas sociais
  const proofs = [
    { id: 1, userName: 'João Silva', action: 'Mutirão de Limpeza' },
    { id: 2, userName: 'Maria Oliveira', action: 'Doação de Sangue' },
  ];

  return (
    <ContentWrapper title="Tela de Aceite de Provas Sociais">
      <ul className={styles.list}>
        {proofs.map(proof => (
          <li key={proof.id} className={styles.listItem}>
            <div>
              <p className={styles.userName}>{proof.userName}</p>
              <p className={styles.action}>{proof.action}</p>
            </div>
            <div className={styles.buttons}>
              <button className={`${styles.button} ${styles.approve}`}>Aprovar</button>
              <button className={`${styles.button} ${styles.reject}`}>Rejeitar</button>
            </div>
          </li>
        ))}
      </ul>
    </ContentWrapper>
  );
};

export default AcceptancePage;
